xwikidoc.content:
{{velocity}}
== OA 用户数据同步 ==

(% class="xform" %)
* **数据日期**：默认同步前一天（`xwiki.oa-sync.source.<type>.date-offset-days`），手动触发可传 `date=YYYYMMDD`
* **定时**：每天 05:00，可在「应用 → Scheduler」修改 cron（同一任务会同步所有已启用的来源：行员/外包）
* **记录**：每种来源保留最近 10 条
* **状态说明**：SUCCESS=全部成功；PARTIAL_FAILURE=部分失败；FAILURE=整体失败（详见 errorLog）

## 必须与 REST 端点的 checkAccess(Right.ADMIN) 口径一致（wiki 级）：
## hasAdminRights() 还包含 space 管理员，用它会让 space 管理员看到按钮却永远 403
#if ($xwiki.hasWikiAdminRights())

== 手动触发 ==

{{html}}
<p>
<button class="oa-sync-trigger btn btn-primary" data-type="employee">立即同步：行员</button>
<button class="oa-sync-trigger btn btn-primary" data-type="outsourcing">立即同步：外包</button>
</p>
<script>
(function () {
  function bind(btn) {
    btn.addEventListener('click', function () {
      var type = btn.getAttribute('data-type');
      btn.disabled = true;
      fetch('$request.contextPath/rest/oa-sync/trigger?type=' + type, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: '{}'
      }).then(function (resp) {
        return resp.json().catch(function () { return {}; }).then(function (data) {
          var level = data.status === 'SUCCESS' ? 'done' : 'warning';
          new XWiki.widgets.Notification('[' + data.type + '] ' + data.status + ' 成功=' + data.success + ' 失败=' + data.failed, level);
        });
      }).catch(function (err) {
        new XWiki.widgets.Notification('触发失败：' + err, 'error');
      }).finally(function () {
        btn.disabled = false;
      });
    });
  }
  var btns = document.querySelectorAll('.oa-sync-trigger');
  for (var i = 0; i < btns.length; i++) {
    bind(btns[i]);
  }
})();
</script>
{{/html}}

== Excel 全量导入：科技外包 ==

按 `staff_id` 建号并全部加入「开发中心科技外包组」，只补齐 Excel 中存在的人，可重复执行。

{{html}}
<p>
<input type="file" id="oa-excel-file" accept=".xlsx" />
<button class="btn btn-primary" id="oa-excel-upload">上传并导入</button>
<span id="oa-excel-status" style="margin-left:8px"></span>
<div id="oa-excel-errors" style="margin-top:8px"></div>
</p>
<script>
(function () {
  var fileInput = document.getElementById('oa-excel-file');
  var button = document.getElementById('oa-excel-upload');
  var status = document.getElementById('oa-excel-status');
  function renderErrors(errors) {
    var container = document.getElementById('oa-excel-errors');
    container.textContent = '';
    if (!errors || errors.length === 0) {
      return;
    }
    var title = document.createElement('div');
    title.textContent = '失败明细（共 ' + errors.length + ' 条）:';
    container.appendChild(title);
    var pre = document.createElement('pre');
    // 用 textContent 而不是 innerHTML：错误里含 Excel 原始工号（用户可控输入）
    pre.textContent = errors.join('\n');
    container.appendChild(pre);
  }
  button.addEventListener('click', function () {
    if (!fileInput.files || fileInput.files.length === 0) {
      new XWiki.widgets.Notification('请先选择 .xlsx 文件', 'warning');
      return;
    }
    button.disabled = true;
    status.textContent = '导入中，请勿关闭页面…';
    // 清掉上一次的失败明细，避免本次请求失败时旧内容滞留在页面上
    document.getElementById('oa-excel-errors').textContent = '';
    fetch('$request.contextPath/rest/oa-sync/outsourcing-excel', {
      method: 'POST',
      headers: { 'Content-Type': 'application/octet-stream' },
      body: fileInput.files[0]
    }).then(function (resp) {
      return resp.json().catch(function () { return {}; }).then(function (data) {
        if (resp.ok && typeof data.status === 'string') {
          var level = data.status === 'SUCCESS' ? 'done' : 'warning';
          var summary = '导入完成：总数=' + data.total + ' 新建=' + data.created
            + ' 已存在=' + data.existed + ' 入组=' + data.joinedGroup
            + ' 已在组=' + data.alreadyMember + ' 失败=' + data.failed;
          new XWiki.widgets.Notification(summary, level);
          // 同时留在页面上：Notification 会在 2~5 秒后自动消失，
          // 而一次导入可能持续数分钟，管理员需要能事后回看摘要
          status.textContent = summary;
          // errors 数组一次也没被渲染过，而这张摘要不随导入刷新；
          // 没有它时 PARTIAL_FAILURE 在页面上完全没有可读原因
          renderErrors(data.errors);
        } else {
          var failure = '导入失败：' + (data.message || resp.status);
          new XWiki.widgets.Notification(failure, 'error');
          status.textContent = failure;
        }
      });
    }).catch(function (err) {
      var failure = '导入请求失败：' + err;
      new XWiki.widgets.Notification(failure, 'error');
      status.textContent = failure;
    }).finally(function () {
      button.disabled = false;
    });
  });
})();
</script>
{{/html}}
#else
{{warning}}本页操作需要管理员权限。{{/warning}}
#end

== 最近同步记录 ==

#set ($records = $services.query.xwql('from doc.object(OASync.SyncRecordClass) as records order by doc.creationDate desc').execute())
#if (!$records || $records.size() == 0)
{{info}}暂无同步记录。{{/info}}
#else
|=(% scope="col" %)类型|=(% scope="col" %)数据日期|=(% scope="col" %)触发|=(% scope="col" %)状态|=(% scope="col" %)总数|=(% scope="col" %)成功|=(% scope="col" %)失败|=(% scope="col" %)开始时间|=(% scope="col" %)错误日志
#foreach ($name in $records)
  #set ($recordDoc = $xwiki.getDocument($name))
  #set ($recordObj = $recordDoc.getObject('OASync.SyncRecordClass'))
  #if ($recordObj)
|$recordObj.getValue('syncType')|$recordObj.getValue('syncDate')|$recordObj.getValue('triggerType')|$recordObj.getValue('status')|$recordObj.getValue('totalCount')|$recordObj.getValue('successCount')|$recordObj.getValue('failCount')|$recordObj.getValue('startTime')
#set ($rawErrorLog = $recordObj.getValue('errorLog'))
## 中和花括号，使渲染结果里不可能出现 {{（工号里可含 / ，如 {{/code}} 会闭合 code 宏并注入 wiki 语法）
## 取舍：{ 在 {{code}} 里可能被 HTML 转义后显示成字面量而不是 { —— 安全优先，接受该显示差异
#set ($safeErrorLog = $rawErrorLog.replace('{', '&#123;').replace('}', '&#125;'))
#if ("$!safeErrorLog" != '')
|(% colspan="9" %){{code}}$safeErrorLog{{/code}}
#end
  #end
#end
#end
{{/velocity}}
